<?php $title = __('Collection Report'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="reports/collections"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><a class="btn btn-outline" href="<?= e(url('reports/collections', ['from' => $from, 'to' => $to, 'export' => 'csv'])) ?>"><?= __('CSV') ?></a><button class="btn btn-outline no-print" type="button" onclick="window.print()"><?= __('🖨 Print') ?></button></form>
<div class="alert alert-info"><?= __('Total recovered') ?><?= date_display($from) ?> → <?= date_display($to) ?>: <strong><?= money($sum) ?></strong> (<?= count($rows) ?><?= __('receipts)') ?></div>
<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Receipt') ?></th><th><?= __('Date') ?></th><th><?= __('Customer') ?></th><th><?= __('Deposited Into') ?></th><th><?= __('Reference') ?></th><th class="num"><?= __('Amount') ?></th></tr></thead>
<tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= e($r['receipt_no']) ?></td><td><?= date_display($r['date']) ?></td><td><?= e($r['customer']) ?></td><td><?= e($r['account']) ?></td><td><?= e($r['reference'] ?? '—') ?></td><td class="num"><?= number_format($r['amount'], 2) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6" class="muted"><?= __('No collections in range.') ?></td></tr><?php endif; ?></tbody>
<tfoot><tr><th colspan="5"><?= __('TOTAL') ?></th><th class="num"><?= number_format($sum, 2) ?></th></tr></tfoot></table></div></div>
